import React from 'react';

const HomePage = ({ onNavigate }) => {
    return (
        <div style={{
            color: 'white',
            backgroundColor: '#0f172a',
            minHeight: '100vh',
            padding: '40px',
            fontFamily: 'Sans-Serif',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center'
        }}>
            <div style={{
                maxWidth: '800px',
                textAlign: 'center'
            }}>
                <h1 style={{ 
                    fontSize: '4em', 
                    marginBottom: '20px',
                    textShadow: '2px 2px 4px rgba(0,0,0,0.5)'
                }}>
                    Welcome to QuizMaster
                </h1>

                <p style={{ 
                    fontSize: '1.5em', 
                    marginBottom: '50px',
                    color: '#94a3b8'
                }}>
                    Test your knowledge with our interactive quiz system!
                </p>

                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
                    gap: '30px',
                    marginBottom: '50px'
                }}>
                    <div style={{
                        backgroundColor: 'rgba(59, 130, 246, 0.2)',
                        padding: '30px',
                        borderRadius: '15px',
                        border: '2px solid rgba(59, 130, 246, 0.5)'
                    }}>
                        <h3 style={{ fontSize: '1.8em', marginBottom: '10px' }}>📚</h3>
                        <h4>Multiple Questions</h4>
                        <p style={{ color: '#cbd5e1' }}>Answer a variety of questions</p>
                    </div>

                    <div style={{
                        backgroundColor: 'rgba(34, 197, 94, 0.2)',
                        padding: '30px',
                        borderRadius: '15px',
                        border: '2px solid rgba(34, 197, 94, 0.5)'
                    }}>
                        <h3 style={{ fontSize: '1.8em', marginBottom: '10px' }}>🎯</h3>
                        <h4>Real-time Scoring</h4>
                        <p style={{ color: '#cbd5e1' }}>See your score as you go</p>
                    </div>

                    <div style={{
                        backgroundColor: 'rgba(168, 85, 247, 0.2)',
                        padding: '30px',
                        borderRadius: '15px',
                        border: '2px solid rgba(168, 85, 247, 0.5)'
                    }}>
                        <h3 style={{ fontSize: '1.8em', marginBottom: '10px' }}>⭐</h3>
                        <h4>Grade Results</h4>
                        <p style={{ color: '#cbd5e1' }}>Get your final grade</p>
                    </div>
                </div>

                <button 
                    onClick={() => onNavigate('quiz')}
                    style={{
                        padding: '20px 60px',
                        fontSize: '24px',
                        cursor: 'pointer',
                        backgroundColor: '#3b82f6',
                        color: 'white',
                        border: 'none',
                        borderRadius: '10px',
                        boxShadow: '0 10px 25px rgba(59, 130, 246, 0.5)',
                        transition: 'all 0.3s',
                        fontWeight: 'bold'
                    }}
                    onMouseOver={(e) => {
                        e.target.style.transform = 'translateY(-3px)';
                        e.target.style.boxShadow = '0 15px 35px rgba(59, 130, 246, 0.6)';
                    }}
                    onMouseOut={(e) => {
                        e.target.style.transform = 'translateY(0)';
                        e.target.style.boxShadow = '0 10px 25px rgba(59, 130, 246, 0.5)';
                    }}
                >
                    Start Quiz
                </button>
            </div>
        </div>
    );
};

export default HomePage;
